<style>
:root{color-scheme:light;--pi-ink:#171b19;--pi-muted:#737373;--pi-edge:#e8e8e8;--pi-bg:#f7f7f8;--pi-nav:#ffffff;--pi-accent:#f9941d;--pi-accent-ink:#9b4d00;--pi-accent-soft:#fff1e0;--pi-panel-radius:14px;--pi-nav-radius:10px;--pi-touch:44px;--pi-content-max:1380px;--pi-shadow:0 6px 24px #171b1909}
*{box-sizing:border-box}body{margin:0;background:var(--pi-bg);color:var(--pi-ink);font:15px/1.55 Arial,Helvetica,sans-serif}
.pi-layout{display:grid;grid-template-columns:245px minmax(0,1fr);min-height:100dvh;align-items:start}.pi-sidebar{background:var(--pi-nav);color:var(--pi-ink);border-right:1px solid var(--pi-edge);padding:28px 22px;position:sticky;top:0;max-height:100dvh;overflow-y:auto}
.pi-brand{font-size:25px;font-weight:800;letter-spacing:-.04em}.pi-brand>span{color:var(--pi-accent)}.pi-brand img{display:block;width:190px;max-width:100%;height:auto}.pi-brand small{display:block;color:var(--pi-muted);font-size:12px;letter-spacing:0;font-weight:400}
.pi-sidebar nav{margin-top:28px}.pi-sidebar ul{list-style:none;padding:0;display:grid;gap:6px}.pi-sidebar li>span{display:flex;align-items:center;min-height:var(--pi-touch);padding:11px 14px;border-radius:var(--pi-nav-radius);color:#5c605d;font-size:13px;line-height:1.4}.pi-sidebar .pi-current{background:var(--pi-accent-soft);color:var(--pi-accent-ink);font-weight:700;box-shadow:inset 3px 0 var(--pi-accent)}
.pi-sidebar-note{font-size:12px;color:var(--pi-muted);border-top:1px solid var(--pi-edge);padding-top:18px}
.pi-main{max-width:var(--pi-content-max);width:100%;padding:32px clamp(18px,4vw,52px) 64px;margin:0 auto;min-width:0}.pi-header{display:flex;justify-content:space-between;gap:18px;align-items:center;flex-wrap:wrap;margin-bottom:24px}
h1{font-size:clamp(26px,3vw,36px);letter-spacing:-.035em;margin:4px 0}h2{font-size:18px;margin:0 0 14px}p{margin:8px 0}.pi-eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.1em;font-weight:800;color:var(--pi-accent-ink)}.pi-muted{color:var(--pi-muted);font-size:13px}
.pi-content{display:grid;gap:20px;margin-top:24px}.pi-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.pi-grid-two{grid-template-columns:repeat(2,minmax(0,1fr))}
.pi-panel{min-width:0;border:1px solid var(--pi-edge);background:#fff;border-radius:var(--pi-panel-radius);padding:24px;box-shadow:var(--pi-shadow);overflow-wrap:anywhere}.pi-service h2{margin-top:18px}
.pi-badge{display:inline-block;border:1px solid currentColor;border-radius:99px;padding:4px 10px;font-size:12px;font-weight:700;overflow-wrap:anywhere}.pi-tone-neutral{background:#f0f4f8;color:#45556c}.pi-tone-info{background:#eef6ff;color:#164b87}.pi-tone-success{background:#edf8f0;color:#256239}.pi-tone-warning{background:#fff7e6;color:#78520c}.pi-tone-error{background:#fff0f0;color:#972b2b}
.pi-message{padding:16px 20px;border:1px solid currentColor;border-radius:12px;overflow-wrap:anywhere}.pi-message p{font-size:13px;margin-bottom:0}.pi-metric-label{color:var(--pi-muted);font-size:14px;font-weight:500}.pi-number{font-size:32px;font-weight:800;letter-spacing:-.04em}
.pi-table-wrap{overflow-x:auto;border-radius:8px}.pi-table-hint{margin:0 0 8px}.pi-table-wrap table{min-width:36rem}table{border-collapse:collapse;width:100%;text-align:left}caption{text-align:left;font-weight:700;padding:12px 8px}th,td{padding:14px 8px;border-bottom:1px solid var(--pi-edge);overflow-wrap:anywhere}th{font-size:12px;color:var(--pi-muted)}td{font-size:14px}
.pi-list{padding-left:22px}.pi-list li{padding:8px 0;border-bottom:1px solid var(--pi-edge)}.pi-empty{padding:24px 12px;text-align:center;color:var(--pi-muted)}.pi-loading{display:flex;align-items:center;gap:12px;padding:16px}.pi-skeleton{display:inline-block;width:40px;height:18px;border-radius:6px;background:#e8e8e8}
.pi-skip{position:absolute;top:8px;left:8px;transform:translateY(-180%);background:#fff;color:var(--pi-accent-ink);padding:10px;z-index:10}.pi-skip:focus{transform:none}a:focus-visible,[tabindex]:focus-visible{outline:3px solid #b75c00;outline-offset:4px}footer{text-align:center;color:var(--pi-muted);font-size:12px;margin-top:28px}
@media(max-width:1050px){.pi-layout{grid-template-columns:1fr;align-content:start}.pi-sidebar{padding:18px 22px;border-right:0;border-bottom:1px solid var(--pi-edge);position:static;max-height:none;overflow:visible}.pi-sidebar nav{margin-top:16px}.pi-sidebar ul{display:flex;overflow-x:auto;gap:6px;scroll-snap-type:x proximity;padding:0 0 8px}.pi-sidebar li{flex:0 0 auto;scroll-snap-align:start}.pi-sidebar li>span{white-space:nowrap}.pi-sidebar-note{display:none}.pi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:640px){.pi-header{display:block}.pi-header>.pi-badge{margin-top:12px}.pi-sidebar{padding:14px 16px}.pi-sidebar ul{padding-bottom:8px}.pi-sidebar li>span{font-size:12px}.pi-grid{grid-template-columns:1fr}.pi-panel{padding:18px}.pi-main{padding:22px 16px 48px}}
.pi-stage-title{margin-top:16px}.pi-journey-progress{width:100%;height:12px;accent-color:var(--pi-accent)}
.pi-journey{padding-left:24px;margin-bottom:0}.pi-journey li{padding:18px 0 18px 12px;border-bottom:1px solid var(--pi-edge)}.pi-journey li:last-child{border:0}.pi-journey h3{font-size:16px;margin:10px 0 4px}.pi-journey p{color:var(--pi-muted)}
.pi-record{margin:16px 0}.pi-record>div{display:grid;grid-template-columns:minmax(0,150px) minmax(0,1fr);gap:12px;padding:10px 0;border-bottom:1px solid var(--pi-edge)}.pi-record dt{font-size:13px;color:var(--pi-muted)}.pi-record dd{margin:0;min-width:0}
.pi-request-list{list-style:none;margin:0;padding:0;display:grid;gap:20px}.pi-request-list>li{min-width:0}
.pi-update-history{margin-top:20px;border-top:1px solid var(--pi-edge);padding-top:16px}.pi-update-history h4{font-size:15px;margin:0 0 8px}.pi-updates{padding-left:24px}.pi-updates li{padding:10px 0 10px 8px}
@media(max-width:1050px){.pi-record>div{grid-template-columns:minmax(0,1fr);gap:4px}}

/* Comportamento comum a todas as telas: estados acessíveis, espaçamento e pouco ruído visual. */
.pi-primary-action{display:inline-flex;justify-content:center;align-items:center;min-height:var(--pi-touch);gap:10px;padding:10px 18px;border:1px solid var(--pi-accent);border-radius:var(--pi-nav-radius);background:var(--pi-accent);color:var(--pi-ink);font-weight:700;text-decoration:none}
.pi-primary-action:hover{filter:brightness(.97)}.pi-primary-action:focus-visible{outline:3px solid #b75c00;outline-offset:3px}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
</style>
